+                .unwrap(),
+            )]
+            .into(),
+        );
+    }
+    let app = build_router(Arc::new(ctx));
+    for (path, prompt, _) in prompts {
+        for (salt, namespace) in [
+            (None, None),
+            (Some(Value::Null), None),
+            (Some(json!("")), None),
+            (Some(json!("tenant-a")), Some("tenant-a")),
+            (Some(json!("租户-B")), Some("租户-B")),
+            (Some(json!([""])), None),
+            (Some(json!(["tenant-a"])), Some("tenant-a")),
+            (Some(json!(["租户-B"])), Some("租户-B")),
+        ] {
